CAT_I = "I - Drug Investigations"

VEHICLE_QUESTIONS = j(
    "May I see your authority card? (Red Book 10.2; RTA s.123 - non-uniformed officer must declare office and produce ID on demand)",
    "What is your name, rank and service number; what is your vehicle number?",
    "Why are you stopping/searching my car? (Red Book 10.2)",
    "Am I being investigated or suspected of an offence? Which one?",
    "Am I under arrest? Am I free to go once you have inspected my licence?",
)
VEHICLE_VERIFY = j(
    ID_CHECK,
    "Stop safely when signalled by a uniformed officer (RTA s.55; PA s.24(3), s.26(2) make failure to stop an offence)",
    "Produce driving licence and insurance certificate on request (RTA s.58(1)-(2)); give name, NRIC, address (Red Book 10.3)",
    "Ask the officer to state the ground for any search (PA s.24(1)(b) requires reasonable grounds to suspect the vehicle is used in an offence)",
    "Stay with the vehicle and watch the search; do not interfere",
)

